<script>
"use strict";
/* ==== MATH:BEGIN ==== */
const RAD = Math.PI / 180;
const TAU = Math.PI * 2;
const norm360 = a => ((a % 360) + 360) % 360;

// Períodos e raios orbitais (dias, AU). Marte: 686,98 d ≈ 1,88 anos terrestres.
const PE = 365.25, PM = 686.98;
const AU_E = 1.0, AU_M = 1.524;
const EARTH_A0 = 0; // a Terra parte do ângulo 0 no dia 0

const BODIES = [
  { name:"Mercury", au:0.387, per:87.97,  a0:200,  r:4.2, color:"#b3a596" },
  { name:"Venus",   au:0.723, per:224.70, a0:318,  r:6.6, color:"#e7c873" },
  { name:"Earth",   au:1.0,   per:365.25, a0:EARTH_A0, r:7.2, color:"#5b9bd5" },
  { name:"Mars",    au:1.524, per:686.98, a0:null,  r:5.6, color:"#d9704b" }
];

// ---- Transferência de Hohmann 1 AU <-> 1.524 AU ----
const at = (AU_E + AU_M) / 2;              // semieixos maior da órbita de transferência
const cc = (AU_M - AU_E) / 2;              // distância focos–centro
const bb = Math.sqrt(at * at - cc * cc);   // semieixos menor (= sqrt(1.524))
const ee = cc / at;                        // excentricidade
const outDays = 0.5 * PE * Math.pow(at, 1.5); // ≈ 259 d (meio ano elíptico)
const S = 360 * outDays / PE;              // varrimento da Terra num voo de ida/volta

// Marte tem de estar à frente da Terra em φ no momento da partida, de modo a
// que, quando a nave complete meio elipse (180°), Marte chegue ao afélio.
const MARS_A0 = norm360(180 - 360 * outDays / PM); // ≈ 44°

// Janela de regresso: no arranque do voo de volta, a relatividade Marte–Terra
// tem de ser S - 180 (a Terra deve "apanhar" a nave no perigeu da volta).
const drift = 360 / PE - 360 / PM;                          // rel. decresce a 0.4616°/d
const rel1 = norm360(180 - S);                              // rel. (Marte−Terra) à chegada
const relTarget = norm360(S - 180);
let stayDays = norm360(rel1 - relTarget) / drift;
if (!(stayDays > 0)) stayDays = 360 / drift;
const stayEnd = outDays + stayDays;
const totDays = outDays + stayDays + outDays;               // ≈ 972 d

function kepler(M) { // resolve E - e·sen E = M (Newton)
  let E = M;
  for (let i = 0; i < 20; i++) E -= (E - ee * Math.sin(E) - M) / (1 - ee * Math.cos(E));
  return E;
}
function dir(deg) { const a = deg * RAD; return [Math.cos(a), Math.sin(a)]; }
function posOf(au, a0, per, d) { // ângulo = a0 + 360·d/per (mod 360), x = r·cos, y = r·sen
  const u = dir(norm360(a0 + 360 * d / per));
  return [au * u[0], au * u[1]];
}
const earthA   = d => norm360(EARTH_A0 + 360 * d / PE);
const marsA    = d => norm360(MARS_A0 + 360 * d / PM);
const earthPos = d => posOf(AU_E, EARTH_A0, PE, d);
const marsPos  = d => posOf(AU_M, MARS_A0, PM, d);

// Posição (AU) da nave num dia de missão.
function shipAt(raw) {
  const d = Math.max(0, raw);
  if (d <= outDays) { // ida: perigeu = posição da Terra no dia 0, E: 0 → π
    const E = kepler(Math.PI * d / outDays);
    const u = dir(earthA(0)), n = [-u[1], u[0]];
    const k = at * Math.cos(E) - cc, q = bb * Math.sin(E);
    return [k * u[0] + q * n[0], k * u[1] + q * n[1]];
  }
  if (d <= stayEnd) return marsPos(d); // espera: colada a Marte
  if (d <= totDays) { // volta: afélio = posição de Marte no arranque, E: π → 2π
    const E = kepler(Math.PI * (1 + (d - stayEnd) / outDays));
    const u = dir(marsA(stayEnd) + 180), n = [-u[1], u[0]];
    const k = at * Math.cos(E) - cc, q = bb * Math.sin(E);
    return [k * u[0] + q * n[0], k * u[1] + q * n[1]];
  }
  return earthPos(d); // missão concluída: nave com a Terra
}
/* ==== MATH:END ==== */

// ---- Contrato de verificação ----
window.__bench = {
  bodies: BODIES.map(b => ({ name: b.name, auRadius: b.au, periodDays: b.per, angleDeg0: b.name === "Mars" ? MARS_A0 : b.a0 })),
  mission: {
    departurePhaseAngleDeg: norm360(MARS_A0 - EARTH_A0),
    outboundDays: outDays,
    stayDays: stayDays,
    returnDays: outDays,
    totalDays: totDays
  },
  setMissionDay(day) {
    day = Number(day);
    if (Number.isFinite(day) && day >= 0) simDay = day;
  },
  getState() {
    const p = shipAt(simDay);
    return { missionDay: simDay, shipAU: { x: p[0], y: p[1] } };
  }
};

// ---- Animação ----
let simDay = 0, paused = false, dps = 1;
const $ = id => document.getElementById(id);
const el = { phase: $("phase"), day: $("day"), total: $("total"),
             fpsI: $("fpsI"), fpsA: $("fpsA"), spd: $("spd"), pause: $("pause"), hint: $("hint") };
el.total.textContent = Math.round(totDays).toLocaleString("pt-PT");
el.hint.textContent = `φ de partida ≈ ${MARS_A0.toFixed(1)}° · voo ≈ ${outDays.toFixed(0)} d · ` +
                      `espera ≈ ${stayDays.toFixed(0)} d · volta ≈ ${outDays.toFixed(0)} d · total ≈ ${Math.round(totDays)} d` +
                      ` · órbitas: 0,39 / 0,72 / 1,00 / 1,52 AU`;

function phaseOf(d) {
  if (d < 1e-9)      return "🧭 Janela de lançamento — partida da Terra";
  if (d < outDays)   return "🚀 Transferência de Hohmann Terra → Marte";
  if (d <= stayEnd)  return "🔴 Em Marte — espera pela janela de regresso";
  if (d <= totDays)  return "🛰 Transferência de regresso Marte → Terra";
  return "🏁 Missão concluída — nave na Terra";
}

const cv = $("cv"), ctx = cv.getContext("2d");
let W = 0, H = 0, stars = [];
function makeStars() {
  stars = [];
  const n = Math.round(W * H / 9000);
  for (let i = 0; i < n; i++)
    stars.push([Math.random() * W, Math.random() * H, 0.5 + Math.random() * 1.1, 0.15 + Math.random() * 0.45]);
}
function resize() {
  const dpr = window.devicePixelRatio || 1;
  W = window.innerWidth; H = window.innerHeight;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  cv.style.width = W + "px"; cv.style.height = H + "px";
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  makeStars();
}
window.addEventListener("resize", resize);
resize();

const toX = (x, px) => W / 2 + x * px;
const toY = (y, px) => H / 2 - y * px;

// Trajetória completa (estática) para referência
const fullPath = (() => {
  const pts = [], N = 160;
  for (let i = 0; i <= N; i++) pts.push(shipAt(outDays * i / N));
  for (let i = 1; i <= 24; i++) pts.push(marsPos(outDays + stayDays * i / 24));
  for (let i = 0; i <= N; i++) pts.push(shipAt(stayEnd + outDays * i / N));
  return pts;
})();

function render() {
  const px = (Math.min(W, H) / 2 - 36) / AU_M;
  ctx.fillStyle = "#04070f";
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = "#cdd8ef";
  for (const s of stars) { ctx.globalAlpha = s[3]; ctx.fillRect(s[0], s[1], s[2], s[2]); }
  ctx.globalAlpha = 1;

  // órbitas
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 5]);
  ctx.strokeStyle = "rgba(140,170,220,0.22)";
  for (const b of BODIES) {
    ctx.beginPath();
    ctx.arc(W / 2, H / 2, b.au * px, 0, TAU);
    ctx.stroke();
  }
  ctx.setLineDash([]);

  // Sol
  const g = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, 30);
  g.addColorStop(0, "#fff6d8");
  g.addColorStop(0.4, "#ffc44d");
  g.addColorStop(1, "rgba(255,140,40,0)");
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(W / 2, H / 2, 30, 0, TAU); ctx.fill();
  ctx.fillStyle = "#ffe9a8";
  ctx.beginPath(); ctx.arc(W / 2, H / 2, 9, 0, TAU); ctx.fill();

  // trajetória de referência
  ctx.beginPath();
  fullPath.forEach((p, i) => (i ? ctx.lineTo(toX(p[0], px), toY(p[1], px))
                                : ctx.moveTo(toX(p[0], px), toY(p[1], px))));
  ctx.strokeStyle = "rgba(110,190,255,0.28)";
  ctx.lineWidth = 1;
  ctx.setLineDash([2, 5]);
  ctx.stroke();
  ctx.setLineDash([]);

  // trajetória percorrida
  const dd = Math.min(simDay, totDays);
  if (dd > 1e-6) {
    const N = Math.max(24, Math.min(500, Math.ceil(dd / 2)));
    ctx.beginPath();
    for (let i = 0; i <= N; i++) {
      const p = shipAt(dd * i / N);
      i ? ctx.lineTo(toX(p[0], px), toY(p[1], px)) : ctx.moveTo(toX(p[0], px), toY(p[1], px));
    }
    ctx.strokeStyle = "rgba(140,225,255,0.9)";
    ctx.lineWidth = 1.6;
    ctx.stroke();
  }

  // planetas + etiquetas
  ctx.font = "11px system-ui, sans-serif";
  ctx.textBaseline = "middle";
  for (const b of BODIES) {
    const ang = b.name === "Mars" ? marsA(simDay) : norm360(b.a0 + 360 * simDay / b.per);
    const X = toX(b.au * Math.cos(ang * RAD), px), Y = toY(b.au * Math.sin(ang * RAD), px);
    ctx.beginPath(); ctx.arc(X, Y, b.r, 0, TAU);
    ctx.fillStyle = b.color; ctx.fill();
    ctx.strokeStyle = "rgba(255,255,255,0.25)"; ctx.lineWidth = 1; ctx.stroke();
    const dv = dir(ang);
    const lx = W / 2 + (b.au * px + 15) * dv[0], ly = H / 2 - (b.au * px + 15) * dv[1];
    ctx.fillStyle = "rgba(200,215,240,0.85)";
    ctx.textAlign = dv[0] > 0.35 ? "left" : dv[0] < -0.35 ? "right" : "center";
    ctx.fillText(b.name, lx, ly);
  }

  // nave
  const sp = shipAt(simDay);
  const X = toX(sp[0], px), Y = toY(sp[1], px);
  const q = shipAt(Math.min(simDay + 1.4, totDays + 1));
  const ang = Math.atan2(-(q[1] - sp[1]), q[0] - sp[0]);
  ctx.save();
  ctx.translate(X, Y);
  ctx.rotate(ang);
  ctx.beginPath(); ctx.moveTo(7, 0); ctx.lineTo(-5, 4.4); ctx.lineTo(-5, -4.4); ctx.closePath();
  ctx.fillStyle = "#eaf6ff"; ctx.fill();
  ctx.strokeStyle = "#49e29f"; ctx.lineWidth = 1.2; ctx.stroke();
  ctx.restore();
  ctx.beginPath(); ctx.arc(X, Y, 9.5, 0, TAU);
  ctx.strokeStyle = "rgba(73,226,159,0.55)"; ctx.lineWidth = 1.5; ctx.stroke();

  el.phase.textContent = phaseOf(simDay);
  el.day.textContent = Math.floor(simDay).toLocaleString("pt-PT");
}

el.spd.addEventListener("change", () => { dps = parseFloat(el.spd.value); });
el.pause.addEventListener("click", () => {
  paused = !paused;
  el.pause.textContent = paused ? "▶ Retomar" : "⏸ Pausar";
});

let prevT = performance.now(), t0 = prevT,
    frAcc = 0, frCnt = 0, fpsI = 0, totFrames = 0, totTime = 0;
function tick(now) {
  requestAnimationFrame(tick);
  let dt = (now - prevT) / 1000;
  prevT = now;
  if (dt < 0) dt = 0;
  if (dt > 0.5) dt = 0.5;
  totFrames++; totTime += dt;
  if (!paused) {
    simDay += dt * dps;
    if (simDay > totDays + 365.25) simDay = totDays + 365.25;
  }
  frAcc += dt; frCnt++;
  if (frAcc >= 0.5) { fpsI = frCnt / frAcc; frAcc = 0; frCnt = 0; }
  render();
  const fpsA = totTime > 0 ? totFrames / totTime : 0;
  if (fpsI > 0) el.fpsI.textContent = fpsI.toFixed(1);
  if (fpsA > 0) el.fpsA.textContent = fpsA.toFixed(1);
}
requestAnimationFrame(tick);
</script>
</body>
</html>
